reset role;
select pg_temp.assert_true((select id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1'and provider='bank'and icon_url='https://example.invalid/uploaded-iban.png'from public.payment_methods where code='iban'),'Nadogradnja povezuje raniji IBAN i čuva ID i učitanu ikonu');
set role anon;
select pg_temp.assert_true((select icon_url='https://example.invalid/uploaded-iban.png'from public.payment_methods where code='iban'),'Aktivna IBAN ikona vidljiva je kupcima');
select pg_temp.expect_error('select iban from public.business_settings','Javna ikona ne otkriva privatne podatke bankovnog računa');
select pg_temp.expect_error('select public.configure_bank_method(false)','Posjetitelj ne mijenja IBAN plaćanje');
reset role;set role authenticated;select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',false);
select pg_temp.expect_error('select public.configure_bank_method(false)','Kupac ne isključuje IBAN plaćanje');
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',false);
select pg_temp.expect_error('update public.payment_methods set enabled=false where code=''iban''','Izravni skriveni prekidač ne razdvaja IBAN karticu i glavnu postavku');
select public.configure_bank_method(false);
select pg_temp.assert_true((select not bank_enabled from public.site_settings)and(select not enabled from public.payment_methods where code='iban'),'Skrivanje IBAN kartice isključuje glavnu postavku');
select pg_temp.assert_true(not(public.checkout_options()->>'bank')::boolean,'Skriveni IBAN nije ponuđen u košarici');
set role anon;select pg_temp.assert_true(not exists(select 1 from public.payment_methods where code='iban'),'Skrivena IBAN ikona nije u javnom popisu');
reset role;set role authenticated;select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',false);
update public.site_settings set bank_enabled=true;
select pg_temp.assert_true((select enabled from public.payment_methods where code='iban')and(public.checkout_options()->>'bank')::boolean,'Glavna postavka uključuje istu IBAN karticu i naplatu');
insert into public.payment_methods(code,name,provider)values('custom_paypal_fixture','PayPal','unconnected');
select pg_temp.expect_error('update public.payment_methods set enabled=true where code=''custom_paypal_fixture''','PayPal ikona ne uključuje neintegriranu naplatu');
delete from public.payment_methods where code='iban';
select pg_temp.assert_true((select not bank_enabled from public.site_settings)and not(public.checkout_options()->>'bank')::boolean,'Brisanje IBAN kartice isključuje nove bankovne narudžbe');
select pg_temp.assert_true(exists(select 1 from public.orders where payment_method='bank'and bank_instructions->>'iban'='HR1210010051863000160'and paid_cents=2701),'Brisanje metode čuva stare IBAN upute i potvrđene uplate');
select public.configure_bank_method(true);
select pg_temp.assert_true((select enabled from public.payment_methods where code='iban')and(select bank_enabled from public.site_settings),'Bankovna metoda može se ponovno dodati');
reset role;
